#!/usr/bin/env python3
"""Export the canonical SKILL.md as a standalone prompt; no API calls or writes elsewhere."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "skills" / "llm-agent-resume" / "SKILL.md"
OUTPUT = ROOT / "skills" / "llm_agent_resume_prompt.md"
START = "<!-- RESOURCE_INDEX_START -->"
END = "<!-- RESOURCE_INDEX_END -->"
HEADER = (
    "<!-- Generated by scripts/export_prompt.py. Edit skills/llm-agent-resume/SKILL.md instead. -->\n"
    "> 单文件提示词导出。核心约束自包含，不依赖其他文件；在允许设置指令的宿主中使用，"
    "不宣称普通聊天附件自动成为 System Prompt。\n\n"
)


def render_prompt(source: str) -> str:
    """Drop metadata and the optional resource index, preserving all mandatory instructions."""
    text = source.replace("\r\n", "\n")
    if not text.startswith("---\n"):
        raise ValueError("SKILL.md must start with YAML frontmatter.")
    _, sep, body = text[4:].partition("\n---\n")
    if not sep:
        raise ValueError("Missing closing YAML frontmatter delimiter.")
    if body.count(START) != 1 or body.count(END) != 1:
        raise ValueError("Expected exactly one optional resource index block.")
    start, end = body.index(START), body.index(END)
    if end < start:
        raise ValueError("Resource index markers are out of order.")
    body = body[:start] + body[end + len(END):]
    return HEADER + body.strip() + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check freshness without modifying files")
    args = parser.parse_args()
    try:
        expected = render_prompt(SOURCE.read_text(encoding="utf-8"))
        if args.check:
            current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.exists() else None
            if current != expected:
                print("STALE: run python scripts/export_prompt.py", file=sys.stderr)
                return 1
            print("OK: standalone prompt matches canonical SKILL.md")
            return 0
        OUTPUT.parent.mkdir(parents=True, exist_ok=True)
        # An explicit newline setting keeps generated content stable on Windows.
        with OUTPUT.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(expected)
        print(f"Wrote {OUTPUT.relative_to(ROOT).as_posix()}")
        return 0
    except (OSError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
